from __future__ import annotations

import pytest

from app.core.validators.insz import is_valid_insz


# Known-good synthetic INSZ values. Generated by applying the Mod-97 rule
# to deterministic serials — we never use real-person numbers in tests.
def _build_valid_insz(serial9: str, *, post_2000: bool) -> str:
    base = ("2" + serial9) if post_2000 else serial9
    check = 97 - (int(base) % 97)
    return serial9 + f"{check:02d}"


PRE_2000_VALID = _build_valid_insz("850101001", post_2000=False)
POST_2000_VALID = _build_valid_insz("050101001", post_2000=True)


class TestINSZValidator:
    def test_pre_2000_valid(self) -> None:
        assert is_valid_insz(PRE_2000_VALID) is True

    def test_post_2000_valid(self) -> None:
        assert is_valid_insz(POST_2000_VALID) is True

    def test_invalid_checksum(self) -> None:
        # Flip last two digits — guaranteed mismatch under both rules.
        bad = PRE_2000_VALID[:9] + "00"
        assert is_valid_insz(bad) is False

    @pytest.mark.parametrize("value", ["", "1234567890", "123456789012"])
    def test_wrong_length(self, value: str) -> None:
        assert is_valid_insz(value) is False

    def test_non_digit(self) -> None:
        assert is_valid_insz("8501010010A") is False

    def test_non_string(self) -> None:
        assert is_valid_insz(85010100123) is False  # type: ignore[arg-type]
